// 1. ZAMIAST brać dane z wejścia (które teraz nadpisał Discord), 
// sięgamy "wstecz" do węzła, który miał kompletne dane!
// UWAGA: Upewnij się, że nazwa w nawiasach to DOKŁADNA nazwa Twojego węzła z datami
const formData = $('Wylicz daty powiadomień').first().json;
const body = formData.body || formData;

const imieSolenizanta = body['imie-solenizanta'] || '';
const telefon = body['telefon-kontaktowy'] || '';
const email = body['email-kontaktowy'] || '';
const pakiet = body['pakiet'] || '';
const motyw = body['motyw'] || '';
const dataZabawy = body['data-zabawy'] || '';
const wiek = body['wiek'] || '';
const dodatki = body['dodatki'] || '';

// 2. Pierwsze imię solenizanta do detekcji płci dziecka
const pierwszeImie = imieSolenizanta.split(' ')[0].trim();
const meskieWyjatki = ['kuba', 'barnaba', 'bonawentura', 'jarema', 'kosma'];
let plecDziecka = 'M';
if (pierwszeImie) {
  const imieLower = pierwszeImie.toLowerCase();
  if (imieLower.endsWith('a') && !meskieWyjatki.includes(imieLower)) {
    plecDziecka = 'F';
  }
}

// 3. Słownik zwrotów uzależnionych od płci dziecka
const zwroty = {
  synaCorki: plecDziecka === 'F' ? 'córki' : 'syna',
  solenizantaSolenizantki: plecDziecka === 'F' ? 'Solenizantki' : 'Solenizanta'
};

// 4. Przygotowanie propozycji tematu i treści maila (w formacie HTML)
const emailSubject = `Zapytanie o urodziny - ${pierwszeImie} (${wiek})`;

const emailBody = `Szanowni Państwo,<br><br>

Dziękujemy za przesłanie zapytania o organizację urodzin dla Waszego dziecka!<br><br>

Oto podsumowanie szczegółów imprezy dla <b>${pierwszeImie}</b>:<br>
• Wiek ${zwroty.solenizantaSolenizantki}: <b>${wiek}</b><br>
• Preferowana data zabawy: <b>${dataZabawy || 'Do ustalenia'}</b><br>
• Wybrany motyw / sala: <b>${motyw || 'Brak'}</b><br>
• Wybrany pakiet: <b>${pakiet || 'Brak'}</b><br>
• Zaznaczone dodatki: <b>${dodatki || 'Brak'}</b><br><br>

<b>Dane kontaktowe:</b><br>
• Telefon: ${telefon || 'Nie podano'}<br>
• E-mail: ${email || 'Nie podano'}<br><br>

Nasz zespół wkrótce skontaktuje się z Państwem, aby potwierdzić dostępność terminu i omówić szczegóły tego wyjątkowego dnia.<br><br>

W razie jakichkolwiek pytań lub chęci modyfikacji rezerwacji, prosimy o odpowiedź na tę wiadomość.<br><br>

Z pozdrowieniami,<br>
<b>Zespół Sali Zabaw</b>`;

// 5. Zwracamy z powrotem PEŁEN obiekt JSON (żeby Gmail i kolejne węzły miały wszystko)
return {
  json: {
    ...formData,
    pierwszeImie,
    zwroty,
    emailSubject,
    emailBody
  }
};

