const drafts = $input.all();
const alerts = [];
const now = Date.now();

for (const item of drafts) {
  // Pobieramy czas utworzenia szkicu w milisekundach (internalDate z Gmaila)
  const draftTime = parseInt(item.json.internalDate);
  if (!draftTime) continue;

  // Obliczamy wiek szkicu w godzinach
  const diffHours = (now - draftTime) / (1000 * 60 * 60);
  let alertType = null;

  // Tworzymy okienka czasowe, aby wysłać dany alert tylko RAZ
  if (diffHours >= 1 && diffHours < 7) {
    alertType = "⏳ Czas leci (1 godzina)";
  } else if (diffHours >= 24 && diffHours < 25) {
    alertType = "⚠️ HALO! (Minęły 24 godziny)";
  } else if (diffHours >= 48 && diffHours < 49) {
    alertType = "🚨 OSTATNIE OSTRZEŻENIE (Minęło 48 godzin!)";
  }

  // Jeśli szkic wpada w któreś okienko, szykujemy go do wysyłki na Discord
  if (alertType) {
    alerts.push({
      json: {
        id: item.json.id,
        snippet: item.json.snippet,
        alertType: alertType,
        godziny: Math.floor(diffHours)
      }
    });
  }
}

return alerts;

const dzisiaj = new Date().toISOString().split('T')[0];
const validItems = [];

for (const item of $input.all()) {
  // Pomijamy puste wiersze lub takie, które nie mają wyliczonych dat
  if (!item.json['Data T-7']) continue;

  // Dopisujemy dzisiejszą datę do każdego wiersza, żeby ułatwić pracę zwrotnicy
  item.json.Dzisiaj = dzisiaj;
  validItems.push(item);
}

return validItems;

// Funkcja do wstępnej odmiany imienia w dopełniaczu (dla kogo?)
function odmienImie(imie) {
  if (!imie) return "dziecka";
  imie = imie.trim();
  const lower = imie.toLowerCase();

  if (lower.endsWith('a')) {
    if (['kuba', 'barnaba', 'kosma'].includes(lower)) return imie.slice(0, -1) + 'y';
    if (lower.endsWith('ia') || lower.endsWith('ja')) return imie.slice(0, -1) + (lower.endsWith('ja') ? 'i' : '');
    return imie.slice(0, -1) + 'y'; 
  }
  if (lower.endsWith('ś')) return imie.slice(0, -1) + 'sia';
  if (lower.endsWith('ek')) return imie.slice(0, -2) + 'ka';
  if (lower === 'kacper') return 'Kacpra';
  if (lower === 'piotr') return 'Piotra';
  if (lower === 'paweł') return 'Pawła';
  if (lower.endsWith('o')) return imie;

  return imie + 'a';
}

const validItems = [];

for (const item of $input.all()) {
  const json = item.json;

  // 1. Walidacja marketingowa i telefonu
  if (json['Zgoda telefon marketingowa'] !== "1" && json['Zgoda telefon marketingowa'] !== 1) continue; 
  let cleanPhone = (json['Telefon'] || "").replace(/\D/g, '');
  if (cleanPhone.length === 11 && cleanPhone.startsWith('48')) cleanPhone = cleanPhone.substring(2);
  if (cleanPhone.length !== 9) continue; 

  // 2. Przygotowanie danych dla Gemini
  const pelneImie = json['Imię solenizanta'] || 'Dziecko';
  const pierwszeImie = pelneImie.split(' ')[0].trim();

  // Wstępna propozycja (JS robi 90% roboty z zachowaniem polskich znaków)
  const propozycjaJS = odmienImie(pierwszeImie);

  // Zapisujemy w obiekcie
  json.TelefonWyczyszczony = cleanPhone;
  json.bazoweImie = pierwszeImie;
  json.propozycjaJS = propozycjaJS;

  validItems.push(item);
}

return validItems;
